import{_ as a,c as n,o as i,ag as s}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"MediaWiki for Communities of Interest","description":"","frontmatter":{"title":"MediaWiki for Communities of Interest"},"headers":[],"relativePath":"general/mediawiki-for-communities-of-interest.md","filePath":"general/mediawiki-for-communities-of-interest.md","lastUpdated":null}'),t={name:"general/mediawiki-for-communities-of-interest.md"};function l(o,e,r,d,p,h){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="mediawiki-for-communities-of-interest" tabindex="-1">MediaWiki for Communities of Interest <a class="header-anchor" href="#mediawiki-for-communities-of-interest" aria-label="Permalink to &quot;MediaWiki for Communities of Interest&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><h3 id="is-mediawiki-the-right-choice" tabindex="-1">Is MediaWiki the Right Choice <a class="header-anchor" href="#is-mediawiki-the-right-choice" aria-label="Permalink to &quot;Is MediaWiki the Right Choice&quot;">​</a></h3><h3 id="considerations-before-you-start" tabindex="-1">Considerations Before You Start <a class="header-anchor" href="#considerations-before-you-start" aria-label="Permalink to &quot;Considerations Before You Start&quot;">​</a></h3><ul><li><p>Consider whether your community has permanent file storage when determining whether to allow PDFs and other file types and increasing the file size on the media wiki.</p></li><li><p>You&#39;ll likely want to customize the wiki name and logo. You should also consider customizing terms and privacy agreements.</p></li></ul><h3 id="configuring-mediawiki" tabindex="-1">Configuring MediaWiki <a class="header-anchor" href="#configuring-mediawiki" aria-label="Permalink to &quot;Configuring MediaWiki&quot;">​</a></h3><h3 id="customizing-the-mediawiki" tabindex="-1">Customizing the MediaWiki <a class="header-anchor" href="#customizing-the-mediawiki" aria-label="Permalink to &quot;Customizing the MediaWiki&quot;">​</a></h3><p>You&#39;ll likely want to customize the wiki name and logo. You should also consider customizing terms and privacy agreements.</p><h3 id="file-uploads" tabindex="-1">File Uploads <a class="header-anchor" href="#file-uploads" aria-label="Permalink to &quot;File Uploads&quot;">​</a></h3><p>When determining whether to allow PDFs and other file types and increasing the file size on the media wiki, consider whether your community has permanent file storage.</p><h3 id="extensions-to-consider" tabindex="-1">Extensions to Consider <a class="header-anchor" href="#extensions-to-consider" aria-label="Permalink to &quot;Extensions to Consider&quot;">​</a></h3><h3 id="api-integration" tabindex="-1">API Integration <a class="header-anchor" href="#api-integration" aria-label="Permalink to &quot;API Integration&quot;">​</a></h3><h3 id="enabling-identity-management" tabindex="-1">Enabling Identity Management <a class="header-anchor" href="#enabling-identity-management" aria-label="Permalink to &quot;Enabling Identity Management&quot;">​</a></h3><h3 id="enabling-3d-model-uploads" tabindex="-1">Enabling 3D Model Uploads <a class="header-anchor" href="#enabling-3d-model-uploads" aria-label="Permalink to &quot;Enabling 3D Model Uploads&quot;">​</a></h3><p>This page provides instructions on enabling the upload and display of 3D model files (STL format) on this MediaWiki instance using the <strong>3D</strong> and <strong>3d2png</strong> extensions. It includes setting up the necessary extensions and configurations for handling and rendering 3D files.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before uploading 3D model files, ensure the following extensions are installed:</p><ul><li><p><strong>3D Extension</strong> (For STL file upload)</p></li><li><p><strong>3d2png</strong> (For thumbnail rendering of 3D models)</p></li><li><p><strong>VisualEditor</strong> (Optional but recommended for an enhanced editing experience)</p></li></ul><h3 id="installation-and-configuration" tabindex="-1">Installation and Configuration <a class="header-anchor" href="#installation-and-configuration" aria-label="Permalink to &quot;Installation and Configuration&quot;">​</a></h3><h4 id="_1-allow-3d-file-uploads" tabindex="-1">1. Allow 3D File Uploads <a class="header-anchor" href="#_1-allow-3d-file-uploads" aria-label="Permalink to &quot;1. Allow 3D File Uploads&quot;">​</a></h4><p>Add the following lines to your <code>LocalSettings.php</code> file to enable STL file uploads:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>$wgTrustedMediaFormats[= &#39;application/sla&#39;;</span></span>
<span class="line"><span>$wgFileExtensions[](]) = &#39;stl&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="_2-install-the-3d-extension" tabindex="-1">2. Install the 3D Extension <a class="header-anchor" href="#_2-install-the-3d-extension" aria-label="Permalink to &quot;2. Install the 3D Extension&quot;">​</a></h4><p>Download and install the 3D extension by cloning the repository:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>cd /var/www/html/extensions</span></span>
<span class="line"><span>git clone -b REL1_42 https://gerrit.wikimedia.org/r/mediawiki/extensions/3D</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>After that, load the extension by adding this to the <code>LocalSettings.php</code> file:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>wfLoadExtension(&#39;3D&#39;);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="_3-install-the-3d2png-extension-for-thumbnail-rendering" tabindex="-1">3. Install the 3d2png Extension (for thumbnail rendering) <a class="header-anchor" href="#_3-install-the-3d2png-extension-for-thumbnail-rendering" aria-label="Permalink to &quot;3. Install the 3d2png Extension (for thumbnail rendering)&quot;">​</a></h4><p>Clone the 3d2png repository, install dependencies, and configure:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>git clone -b REL1_42 https://gerrit.wikimedia.org/r/3d2png</span></span>
<span class="line"><span>cd 3d2png</span></span>
<span class="line"><span>npm install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Update <code>LocalSettings.php</code> to tell the 3D extension how to call the thumbnail generator:</p><h5 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h5><p>If you encounter issues during the setup, ensure the following:</p><ul><li>Ensure <strong>xvfb</strong> and other X11 dependencies are installed using the following command:</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>apt-get install libx11-dev libxi-dev libxext-dev xvfb libgl1-mesa-dev libglu1-mesa-dev freeglut3-dev mesa-common-dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><p>Check for missing dependencies or errors in the JavaScript libraries during <code>npm install</code>.</p></li><li><p>If NPM install doesn&#39;t work this may fix it. Make sure that the version of these repos cloned matches with the version of media wiki you are running.</p><ul><li>git clone -b REL1_42 for mediawiki 1.42.*</li></ul></li></ul><h5 id="configuring" tabindex="-1">Configuring <a class="header-anchor" href="#configuring" aria-label="Permalink to &quot;Configuring&quot;">​</a></h5><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>$wg3dProcessor = [</span></span>
<span class="line"><span>    &#39;/usr/bin/xvfb-run&#39;,</span></span>
<span class="line"><span>    &#39;-a&#39;,</span></span>
<span class="line"><span>    &#39;-s&#39;,</span></span>
<span class="line"><span>    &#39;-ac -screen 0 1280x1024x24&#39;,</span></span>
<span class="line"><span>    &#39;/var/www/html/extensions/3d2png/3d2png.js&#39;</span></span>
<span class="line"><span>];</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h4 id="_4-optional-install-multimediaviewer-extension" tabindex="-1">4. Optional: Install MultimediaViewer Extension <a class="header-anchor" href="#_4-optional-install-multimediaviewer-extension" aria-label="Permalink to &quot;4. Optional: Install MultimediaViewer Extension&quot;">​</a></h4><p>For better interaction with 3D models (move, pan, zoom), install the <strong>MultimediaViewer</strong> extension and add the following configuration to <code>LocalSettings.php</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>$wgMediaViewerExtensions[= &#39;mmv.3d&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="usage-instructions" tabindex="-1">Usage Instructions <a class="header-anchor" href="#usage-instructions" aria-label="Permalink to &quot;Usage Instructions&quot;">​</a></h3><p>Once the extensions are installed and configured:</p><h4 id="_1-upload-3d-model-files" tabindex="-1">1. Upload 3D Model Files <a class="header-anchor" href="#_1-upload-3d-model-files" aria-label="Permalink to &quot;1. Upload 3D Model Files&quot;">​</a></h4><p>Navigate to the <a href="Special:Upload" target="_blank" rel="noreferrer">Special:Upload</a> page and upload your <code>.stl</code> files.</p><h4 id="_2-view-3d-models" tabindex="-1">2. View 3D Models <a class="header-anchor" href="#_2-view-3d-models" aria-label="Permalink to &quot;2. View 3D Models&quot;">​</a></h4><p>Uploaded 3D models will be displayed interactively on their file pages. Thumbnails will be automatically generated using the <code>3d2png</code> service.</p><p>[Building]</p>`,48)])])}const m=a(t,[["render",l]]);export{u as __pageData,m as default};
